INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A sewing line has 5 operations with SAMs: 0.45, 0.60, 0.30, 0.75, 0.50 minutes. The line runs with exactly ONE operator per operation (no parallel machines). At 100% efficiency over a 480-minute shift, what is the line''s MAXIMUM possible output (in pieces), and which operation determines this ceiling?', '["640 pieces, determined by the SLOWEST (bottleneck) operation: 480/0.75 = 640 — every other operation, despite having spare capacity, cannot produce MORE finished garments than the bottleneck allows, since a garment isn''t complete until it passes through ALL operations","1,067 pieces, incorrectly calculated using the FASTEST operation (0.30 SAM) as if it determined the line''s output","728 pieces, incorrectly calculated using the AVERAGE SAM (0.52) across all 5 operations","2,400 pieces, incorrectly summing all 5 individual operations'' theoretical outputs rather than recognizing the line''s output is capped by its single slowest station"]'::jsonb, '640 pieces, determined by the SLOWEST (bottleneck) operation: 480/0.75 = 640 — every other operation, despite having spare capacity, cannot produce MORE finished garments than the bottleneck allows, since a garment isn''t complete until it passes through ALL operations', 'With one operator per operation and no parallel machines, the line''s overall output rate is capped by its SLOWEST operation (highest SAM = 0.75 min), since a complete garment requires passing through every single operation in sequence: 480 minutes ÷ 0.75 min/piece = 640 pieces — this directly applies the earlier bottleneck/Theory-of-Constraints principle: faster operations simply sit idle waiting for work once they''ve outpaced the bottleneck, so their individual higher capacity is wasted rather than adding to the line''s total output.', 3, '{"line-bottleneck-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'Using the previous question''s line (SAMs: 0.45, 0.60, 0.30, 0.75, 0.50), the line balancer wants to eliminate the bottleneck by assigning 2 operators (running 2 parallel machines) to the 0.75-SAM operation ONLY, while keeping all other operations at 1 operator each. What is the NEW bottleneck operation, and the new maximum output at 480 minutes, 100% efficiency?', '["The 0.75-SAM operation is now effectively 0.375 SAM/piece with 2 parallel operators, making the 0.60-SAM operation (Operation 2) the NEW bottleneck: 480/0.60 = 800 pieces","The line has no bottleneck at all once any operation gets 2 operators, allowing theoretically infinite output","The bottleneck stays at the same 0.75-SAM operation regardless of adding a second parallel operator, since SAM per piece never changes with operator count","New output = 640 × 2 = 1,280 pieces, incorrectly assuming doubling ONE operation''s capacity doubles the ENTIRE line''s total output"]'::jsonb, 'The 0.75-SAM operation is now effectively 0.375 SAM/piece with 2 parallel operators, making the 0.60-SAM operation (Operation 2) the NEW bottleneck: 480/0.60 = 800 pieces', 'Adding a second parallel operator to the 0.75-SAM operation HALVES its effective per-piece time contribution to the line''s throughput rate (2 operators working in parallel on identical copies of that operation means the STATION can now process a piece every 0.375 minutes on average) — this operation is no longer the bottleneck; the NEW slowest operation becomes Operation 2 at 0.60 SAM, giving new max output = 480/0.60 = 800 pieces — illustrating that fixing ONE bottleneck simply reveals the NEXT-slowest operation as the new limiting constraint, a core Theory-of-Constraints insight, rather than unlocking unlimited or proportionally-doubled output.', 3, '{"line-rebalancing-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A garment costing sheet shows: Fabric cost $3.20/pc, Trim cost $0.85/pc, CM (labor) cost $1.40/pc, factory overhead 35% of CM, and the factory''s target profit margin is 12% of TOTAL cost (fabric+trim+CM+overhead). What is the FOB selling price per piece?', '["Overhead = 0.35×$1.40=$0.49. Total cost = 3.20+0.85+1.40+0.49 = $5.94. Profit = 0.12×$5.94=$0.7128. FOB price ≈ $6.65","FOB price = $5.94 + 12% flat markup on fabric cost only ($0.384) = $6.32, incorrectly applying the margin to only one cost component instead of total cost","FOB price = fabric+trim+CM only ($5.45), incorrectly omitting overhead and profit margin entirely from the calculation","FOB price = $5.94 × 1.35 = $8.02, incorrectly reapplying the overhead percentage a second time as if it were the profit margin"]'::jsonb, 'Overhead = 0.35×$1.40=$0.49. Total cost = 3.20+0.85+1.40+0.49 = $5.94. Profit = 0.12×$5.94=$0.7128. FOB price ≈ $6.65', 'Step 1: Overhead = 35% of CM = 0.35 × $1.40 = $0.49. Step 2: Total cost = fabric+trim+CM+overhead = $3.20+$0.85+$1.40+$0.49 = $5.94. Step 3: Profit margin = 12% of total cost = 0.12 × $5.94 = $0.7128. Step 4: FOB price = total cost + profit = $5.94 + $0.71 ≈ $6.65 — this multi-step costing calculation requires correctly sequencing THREE separate percentage-based calculations (overhead on CM only, then margin on the full accumulated total), and applying any percentage to the wrong base (as the distractors do) produces a meaningfully wrong final price.', 3, '{"FOB-costing-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A production manager needs to calculate a new sewing line''s required NUMBER OF OPERATORS to achieve a target output of 1,200 pieces/day (480-minute shift) for a style with total garment SAM of 18.5 minutes (sum of all operations), assuming the line runs at 75% overall line efficiency. Using the formula: Operators = (Output × Total SAM) / (Shift minutes × Efficiency), how many operators are needed?', '["46.25 → 47 operators (rounding up), correctly calculating (1,200×18.5)/(480×0.75) = 22,200/360 = 61.67... recompute carefully","62 operators (rounding up from 61.67), correctly calculating (1,200×18.5)/(480×0.75)=22,200/360≈61.67","35 operators, incorrectly omitting the efficiency factor from the denominator entirely","27 operators, incorrectly dividing total SAM by output instead of multiplying"]'::jsonb, '62 operators (rounding up from 61.67), correctly calculating (1,200×18.5)/(480×0.75)=22,200/360≈61.67', 'Required operators = (Target Output × Total SAM) ÷ (Shift Minutes × Efficiency) = (1,200 × 18.5) ÷ (480 × 0.75) = 22,200 ÷ 360 ≈ 61.67, which rounds UP to 62 operators (since a fractional operator isn''t practically possible, and rounding down would fall short of the target output) — this formula essentially calculates total ''earned minutes'' needed (output×SAM) and divides by actual available productive minutes per operator (shift minutes × efficiency), correctly accounting for the fact that NOT all shift time converts to productive output at less than 100% efficiency.', 3, '{"operator-requirement-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory''s ''Right First Time'' (RFT) rate is 88% for a specific style, meaning 12% of garments require SOME rework before passing final inspection. If the line produces 2,000 pieces in a day and REWORK takes an average of 3.5 additional minutes per reworked garment, how many TOTAL EXTRA labor-minutes does rework consume that day?', '["840 extra minutes, correctly calculating 2,000×0.12=240 reworked garments, ×3.5 min each = 840 minutes","700 extra minutes, incorrectly using 88% (the PASS rate) instead of 12% (the rework rate) as the base for the reworked-garment count","7,000 extra minutes, incorrectly treating ALL 2,000 garments as needing rework rather than just the 12% RFT-failing portion","3.5 minutes total, incorrectly reporting only the per-garment rework time as if it were the day''s total rework burden"]'::jsonb, '840 extra minutes, correctly calculating 2,000×0.12=240 reworked garments, ×3.5 min each = 840 minutes', 'Number of reworked garments = 2,000 × 0.12 (the FAILING 12%, not the 88% RFT pass rate) = 240 garments. Total extra rework minutes = 240 × 3.5 = 840 minutes — this is a direct, practical illustration of the earlier RFT-vs-final-pass-rate concept: 840 ''hidden'' extra labor-minutes (equivalent to roughly 1.75 extra operators'' worth of a full shift, using the earlier 480-minute basis) is a real, substantial productivity cost that a simple ''final pass rate'' metric alone wouldn''t surface, reinforcing why RFT is tracked as a distinct efficiency-loss metric.', 3, '{"RFT-rework-cost-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory compares two cutting room options for the SAME order: Option A (manual cutting, marker efficiency 78%) vs Option B (automated CNC cutting, marker efficiency 85%), for a fabric costing $4.50/meter, where the order requires cutting pieces totaling 3,200 linear-meter-equivalents of ACTUAL pattern area (i.e., fabric that would be consumed at 100% marker efficiency). How much MORE total fabric cost does Option A incur compared to Option B, due to the marker efficiency difference alone?', '["Option A fabric needed = 3,200/0.78 = 4,102.6m; Option B = 3,200/0.85 = 3,764.7m. Difference = 337.9m × $4.50/m ≈ $1,520.55 MORE for Option A","Both options require identical fabric consumption regardless of marker efficiency, making this cost comparison technically meaningless","Difference = (0.85−0.78) × $4.50 = $0.315 total, incorrectly treating the efficiency percentage-point gap as if it were directly a dollar cost rather than requiring the full fabric-consumption recalculation","Option A actually costs LESS than Option B, the reverse of the correct relationship between marker efficiency and total fabric cost"]'::jsonb, 'Option A fabric needed = 3,200/0.78 = 4,102.6m; Option B = 3,200/0.85 = 3,764.7m. Difference = 337.9m × $4.50/m ≈ $1,520.55 MORE for Option A', 'Total fabric consumed = actual-pattern-area ÷ marker efficiency (lower efficiency means proportionally MORE total fabric must be purchased/cut to yield the same usable pattern area, since more fabric is wasted as unused marker scrap). Option A: 3,200/0.78 ≈ 4,102.6m. Option B: 3,200/0.85 ≈ 3,764.7m. Difference ≈ 337.9m, × $4.50/m ≈ $1,520.55 — this directly quantifies the earlier marker-efficiency-cost-impact discussion with real numbers, showing that even a modest-looking 7-percentage-point marker efficiency gap (78% vs 85%) translates into over $1,500 of extra fabric cost on this single order alone.', 3, '{"marker-efficiency-cost-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A quality auditor reviewing a factory''s AQL 2.5 inspection data for a 3,000-piece shipment (sample size per ANSI Z1.4 General Level II Normal tables: 315 pieces, accept number 14, reject number 15) finds 13 major defects in the drawn sample. The factory claims this shipment ''passed comfortably.'' Evaluate this claim precisely.', '["The claim is correct in outcome (13 < 14, accept number), but ''comfortably'' overstates the margin — 13 is only ONE defect below the reject threshold (15) and just one below the accept number (14), meaning this result is actually a narrow, marginal pass, not a comfortable one","The claim is entirely wrong; 13 defects found against an accept number of 14 actually means the shipment FAILED, not passed","The claim is fully accurate with no qualification needed, since 13 is meaningfully below both the accept and reject numbers","AQL sampling plans do not use both an accept number AND a separate reject number, making this scenario''s premise technically incorrect"]'::jsonb, 'The claim is correct in outcome (13 < 14, accept number), but ''comfortably'' overstates the margin — 13 is only ONE defect below the reject threshold (15) and just one below the accept number (14), meaning this result is actually a narrow, marginal pass, not a comfortable one', 'Since 13 defects is LESS than the accept number (14), the shipment technically PASSES per the AQL decision rule — but describing this as a ''comfortable'' pass is misleading: 13 is just ONE defect below both the accept number (14) AND the reject number (15), meaning a nearly identical sample with just slightly worse luck (14 or 15 defects) would have failed — a quality-conscious reviewer should flag this as a narrow, marginal pass warranting closer scrutiny of the underlying production process, not accept the factory''s characterization of a comfortable margin at face value.', 3, '{"AQL-marginal-pass-interpretation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory''s monthly efficiency report shows Line 1 at 82% efficiency producing a style with SAM=12.4 min, and Line 2 at 71% efficiency producing a DIFFERENT style with SAM=6.2 min. A supervisor claims ''Line 1 is clearly the better-performing line since its efficiency% is higher.'' Using EARNED MINUTES per operator-hour as a more complete comparison (Earned minutes/hour = Efficiency% × 60), evaluate this claim.', '["The claim is directly validated by earned-minutes comparison: Line 1 = 0.82×60=49.2 earned min/hour; Line 2 = 0.71×60=42.6 earned min/hour — Line 1 genuinely earns more standard minutes per hour, confirming it IS the better-performing line by this metric too","The claim is invalidated, since Line 2''s LOWER SAM style means its 71% efficiency actually represents MORE physical pieces produced per hour than Line 1''s 82% on a higher-SAM style, making raw piece output the only valid comparison","Efficiency% alone is always a complete, sufficient basis for comparing two lines running different styles, making earned-minutes analysis an unnecessary additional step in this case","Earned minutes per hour cannot be calculated from efficiency% alone without also knowing the exact number of operators on each line"]'::jsonb, 'The claim is directly validated by earned-minutes comparison: Line 1 = 0.82×60=49.2 earned min/hour; Line 2 = 0.71×60=42.6 earned min/hour — Line 1 genuinely earns more standard minutes per hour, confirming it IS the better-performing line by this metric too', 'Efficiency% (unlike raw piece-per-hour output) is ALREADY a SAM-normalized metric (earned minutes ÷ actual minutes worked), which is precisely why it CAN validly be compared across lines running different styles/SAMs, unlike raw piece counts — earned minutes/hour = efficiency% × 60 gives Line 1 = 49.2 and Line 2 = 42.6, confirming Line 1 genuinely converts more of its available time into productive (SAM-weighted) output — this reinforces the earlier efficiency-calculation-normalization principle: efficiency% is specifically DESIGNED to enable this kind of fair cross-style comparison, unlike the raw piece-per-hour metric a less careful supervisor might otherwise default to.', 3, '{"efficiency-percent-comparison-validation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory''s absenteeism rate rises from a normal 3% to 9% on a specific day, on a line with 60 sanctioned operator positions. If each ABSENT operator''s station cannot be covered by a substitute (a common reality for skilled, specific single-needle operations), and the line''s output is directly proportional to operators PRESENT, by what PERCENTAGE does expected daily output drop compared to a normal day, assuming normal-day output already accounts for the normal 3% absenteeism?', '["6 percentage points higher absenteeism translates to a proportional output drop of roughly 6/97 ≈ 6.2% versus the normal day''s already-reduced baseline (60×0.97≈58.2 present operators normally, vs 60×0.91=54.6 present operators today)","Output drops by exactly 9%, incorrectly using the day''s raw absenteeism rate directly as the output-drop percentage without comparing against the normal-day baseline","Output is completely unaffected by absenteeism as long as fewer than 10% of operators are absent, treating 10% as an arbitrary unaffected threshold","Output drops by exactly 6%, incorrectly using the raw percentage-point DIFFERENCE (9%−3%=6%) directly without correctly re-basing it against the normal day''s already-reduced 97%-present baseline"]'::jsonb, '6 percentage points higher absenteeism translates to a proportional output drop of roughly 6/97 ≈ 6.2% versus the normal day''s already-reduced baseline (60×0.97≈58.2 present operators normally, vs 60×0.91=54.6 present operators today)', 'Normal-day operators present = 60×(1−0.03)=58.2. Today''s operators present = 60×(1−0.09)=54.6. Output drop % relative to the NORMAL-day baseline = (58.2−54.6)/58.2 × 100 ≈ 6.2% — the correct comparison must be relative to the NORMAL day''s already-reduced present-operator count (58.2), not the full 60 sanctioned positions and not simply the raw percentage-point gap (6 points), illustrating a subtle but common error in correctly re-basing a percentage comparison against the right reference point.', 3, '{"absenteeism-output-impact"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory negotiates a piece-rate INCENTIVE bonus scheme: operators earn 100% of base wage up to 100% efficiency, PLUS a 0.5% wage bonus for EVERY 1 percentage point of efficiency ABOVE 100%. If an operator''s base daily wage (at exactly 100% efficiency) is $12.00, and this operator actually achieves 118% efficiency today, what is their TOTAL wage for the day?', '["$13.08, correctly calculating: 18 percentage points above 100% × 0.5% bonus each = 9% total bonus; $12.00 × 1.09 = $13.08","$21.20, incorrectly multiplying the base wage directly by the raw efficiency percentage (118%) rather than applying the correct incremental bonus structure only to the ABOVE-100% portion","$12.90, incorrectly applying only 0.5% total bonus (as if it were a single flat bonus) rather than 0.5% for EACH of the 18 percentage points above 100%","$12.00, incorrectly assuming no bonus applies at all despite exceeding 100% efficiency, contradicting the stated incentive scheme structure"]'::jsonb, '$13.08, correctly calculating: 18 percentage points above 100% × 0.5% bonus each = 9% total bonus; $12.00 × 1.09 = $13.08', 'Percentage points above 100% = 118−100 = 18 points. Total bonus rate = 18 × 0.5% = 9%. Total wage = base wage × (1 + bonus rate) = $12.00 × 1.09 = $13.08 — this requires correctly identifying that the bonus applies PER PERCENTAGE POINT above the 100% threshold (not as a single flat bonus, and not to the full raw efficiency percentage), a common structure in real piece-rate/efficiency incentive schemes that requires careful multi-step calculation to apply correctly.', 3, '{"incentive-bonus-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A ''Value Stream Mapping'' (VSM) exercise for a garment order''s full production cycle identifies total elapsed time from fabric receipt to shipment as 21 days, but the SUM of actual VALUE-ADDING processing time (cutting+sewing+finishing+packing, when material is actually being actively worked on) is only 2.3 days. What does this large gap between total cycle time and value-added time most directly reveal?', '["The gap indicates a data error, since total cycle time and value-added time should always be nearly identical in any well-run factory","The vast majority of the 21-day cycle consists of NON-value-adding time — material sitting as WIP inventory, waiting between process stages, in queues, or in transit/storage — representing significant waste (echoing the earlier lean-manufacturing WIP-as-waste principle) and a major opportunity for lead-time reduction if these waiting/queue periods can be minimized through better flow/scheduling","This gap is entirely unavoidable and represents no actionable improvement opportunity of any kind for the factory","Value-adding time should always be LARGER than total cycle time by definition, making this reported data internally contradictory"]'::jsonb, 'The vast majority of the 21-day cycle consists of NON-value-adding time — material sitting as WIP inventory, waiting between process stages, in queues, or in transit/storage — representing significant waste (echoing the earlier lean-manufacturing WIP-as-waste principle) and a major opportunity for lead-time reduction if these waiting/queue periods can be minimized through better flow/scheduling', 'This directly applies the earlier lean-manufacturing WIP-as-waste principle using a formal Value Stream Mapping lens — a stark gap between total cycle time (21 days) and actual value-adding processing time (2.3 days, roughly 11% of the total) reveals that the vast majority of elapsed time is pure WAITING/queuing/WIP-sitting time, not productive work — this is precisely the kind of insight VSM is designed to surface, and it directly points toward lead-time-reduction opportunities (better flow, smaller batch sizes, reduced queue time between stages, similar to the earlier UPS/modular production system flexibility discussion) rather than needing to speed up the actual value-adding work itself, which is already a small fraction of the total cycle.', 3, '{"value-stream-mapping"}'::text[]);
